const incoming = $input.first().json;
const trigger = incoming.body ?? incoming;
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (trigger.schemaVersion !== 1) throw new Error('DISCOVERY_TRIGGER_INVALID');
if (!uuid.test(String(trigger.runId)) || !uuid.test(String(trigger.attemptToken))) throw new Error('DISCOVERY_TRIGGER_INVALID');
const generation = Number(trigger.attemptGeneration);
if (!Number.isInteger(generation) || generation < 1) throw new Error('DISCOVERY_TRIGGER_INVALID');
const sources = Array.isArray(trigger.sources) ? trigger.sources : [];
const source = sources.find((item) => item && item.executionMode === 'automatic' && item.sourceKey === 'campaign_me' && uuid.test(String(item.bindingId)));
if (!source) throw new Error('NO_AUTOMATIC_DISCOVERY_SOURCES');
const maxObservations = Math.min(Math.max(Number(trigger.maxObservations) || 25, 1), 25);
return [{ json: { runId: trigger.runId, programmeId: trigger.programmeId, attemptToken: trigger.attemptToken, attemptGeneration: generation, sourceId: source.bindingId, credentialGeneration: Number(source.credentialGeneration) || 0, maxObservations: maxObservations } }];

const crypto = require('crypto');
const trigger = $('Normalize Trigger').first().json;
const items = $input.all();
const feedFailed = items.some((item) => item.json && (item.json.error || item.json.level === 'error'));
const redirectKeys = new Set(['continue', 'dest', 'destination', 'next', 'redirect', 'redirect_uri', 'redirecturl', 'return', 'returnurl', 'target', 'u', 'url']);
function publicHost(value) {
  return String(value || '').toLowerCase().replace(/\.$/, '').replace(/^www\./, '');
}
function permittedUrl(raw) {
  let parsed;
  try { parsed = new URL(String(raw || '').trim()); } catch { return null; }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') return null;
  if (parsed.username || parsed.password) return null;
  if (publicHost(parsed.hostname) !== 'campaignme.com') return null;
  for (const [key, value] of parsed.searchParams.entries()) {
    if (!redirectKeys.has(key.toLowerCase())) continue;
    if (!/^https?:\/\//i.test(value)) continue;
    try {
      if (publicHost(new URL(value).hostname) !== 'campaignme.com') return null;
    } catch { return null; }
  }
  return parsed.toString();
}
function isoDate(value) {
  if (!value) return null;
  const date = new Date(String(value));
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
}
const observations = [];
if (!feedFailed) {
  for (const item of items) {
    if (observations.length >= trigger.maxObservations) break;
    const row = item.json || {};
    const url = permittedUrl(row.link || row.guid);
    if (!url) continue;
    const title = String(row.title || '').trim().slice(0, 500);
    const excerpt = String(row.contentSnippet || row.content || title).trim().slice(0, 5000);
    const sourceItemKey = String(row.guid || url).trim().slice(0, 512);
    if (!title || !excerpt || !sourceItemKey) continue;
    const publishedAt = isoDate(row.isoDate || row.pubDate);
    observations.push({
      observationId: crypto.randomUUID(),
      sourceItemKey: sourceItemKey,
      contentHash: crypto.createHash('sha256').update(sourceItemKey + '\n' + url + '\n' + title + '\n' + excerpt, 'utf8').digest('hex'),
      sourceReference: { kind: 'public_url', url: url },
      observedAt: new Date().toISOString(),
      publishedAt: publishedAt,
      dateEvidence: { method: publishedAt ? 'feed' : 'page_metadata', precision: publishedAt ? 'day' : 'unknown' },
      kind: 'news',
      title: title,
      excerpt: excerpt,
      companyHints: []
    });
  }
}
const lastKey = observations.length ? observations[observations.length - 1].sourceItemKey : null;
const checkpoint = { cursor: lastKey, providerJobId: null, itemsSeen: observations.length, pagesSeen: feedFailed ? 0 : 1 };
const completion = feedFailed
  ? { status: 'failed', counts: { ingested: 0, duplicate: 0, quarantined: 0, rejected: 0 }, checkpoint: checkpoint, usage: [{ providerRequestId: null, units: 1, unitKind: 'request' }], error: { code: 'source_unavailable', retryable: true } }
  : { status: 'completed', counts: { ingested: observations.filter((item) => item.companyHints.length > 0).length, duplicate: 0, quarantined: observations.filter((item) => item.companyHints.length === 0).length, rejected: 0 }, checkpoint: checkpoint, usage: [{ providerRequestId: null, units: 1, unitKind: 'request' }] };
return [{ json: { trigger: trigger, observations: observations, completion: completion } }];

const crypto = require('crypto');
const mapped = $input.first().json;
const trigger = mapped.trigger;
const nowSeconds = Math.floor(Date.now() / 1000);
function envelope(event, payload) {
  const eventId = crypto.randomUUID();
  const body = {
    schemaVersion: 1,
    event: event,
    eventId: eventId,
    runId: trigger.runId,
    sourceId: trigger.sourceId,
    attemptToken: trigger.attemptToken,
    attemptGeneration: trigger.attemptGeneration,
    credentialGeneration: trigger.credentialGeneration,
    payload: payload
  };
  const rawBody = JSON.stringify(body);
  return {
    rawBody: rawBody,
    claims: {
      iss: 'hrmny-n8n-discovery',
      aud: 'hrmny-os-discovery',
      jti: eventId,
      iat: nowSeconds,
      exp: nowSeconds + 300,
      bodyHash: crypto.createHash('sha256').update(rawBody, 'utf8').digest('hex')
    }
  };
}
const observation = mapped.observations.length
  ? envelope('sales.discovery.observations.v1', { observations: mapped.observations, checkpoint: mapped.completion.checkpoint, usage: mapped.completion.usage })
  : null;
const completion = envelope('sales.discovery.completion.v1', mapped.completion);
const callbackUrl = String($vars.HRMNY_OS_BASE_URL || '').replace(/\/+$/, '') + '/api/integrations/discovery/callback';
if (!/^https:\/\//i.test(callbackUrl)) throw new Error('HRMNY_OS_BASE_URL_UNAVAILABLE');
return [{ json: { hasObservations: Boolean(observation), observation: observation, completion: completion, callbackUrl: callbackUrl } }];
